'use strict';
const photos=[...document.querySelectorAll('[data-photo]')],more=document.querySelector('#more-photos'),filters=[...document.querySelectorAll('[data-album-filter]')];let visibleCount=12,album='all';
const matching=()=>photos.filter(p=>album==='all'||p.dataset.album===album);
function showPhotos(){const matches=matching();photos.forEach(p=>p.hidden=true);matches.slice(0,visibleCount).forEach(p=>p.hidden=false);more.hidden=visibleCount>=matches.length;document.querySelector('#photo-count').textContent=`${matches.length} photos${album==='all'?' across seven events':''}`}
filters.forEach(button=>button.addEventListener('click',()=>{album=button.dataset.albumFilter;visibleCount=12;filters.forEach(b=>b.setAttribute('aria-pressed',String(b===button)));showPhotos()}));
more.addEventListener('click',()=>{const firstNew=matching()[visibleCount];visibleCount+=12;showPhotos();firstNew?.focus()});showPhotos();
const viewer=document.querySelector('#photo-viewer'),image=document.querySelector('#viewer-image'),caption=document.querySelector('#viewer-caption');let selected=0,opener;
function displayPhoto(index){const matches=matching();selected=(index+matches.length)%matches.length;const photo=matches[selected],img=photo.querySelector('img');image.src=photo.href;image.alt=img.alt;caption.textContent=img.alt;document.querySelector('#open-photo').href=photo.href}
photos.forEach(p=>p.addEventListener('click',e=>{e.preventDefault();opener=p;displayPhoto(matching().indexOf(p));viewer.showModal()}));
document.querySelector('#close-photo').addEventListener('click',()=>viewer.close());document.querySelector('#previous-photo').addEventListener('click',()=>displayPhoto(selected-1));document.querySelector('#next-photo').addEventListener('click',()=>displayPhoto(selected+1));viewer.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();displayPhoto(selected+(e.key==='ArrowLeft'?-1:1))}});viewer.addEventListener('click',e=>{if(e.target===viewer)viewer.close()});viewer.addEventListener('close',()=>opener?.focus());
